scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var options = {
        type: "1",
        fileName: "excel.xlsx"
    };
    gridView1.advancedExcelDownload(options);
};
scwin.trigger2_onclick = function(e) {
    var options = {
        type: "1",
        startRowIndex: "0",
        headerExist: "1"
    };
    gridView1.advancedExcelUpload(options);
};
